9	interface ProductHeroProps {
10	  feature: string;
11	  headline: string;
12	  italicWord: string;
13	  subhead: string;
14	  primaryCTA?: { label: string; href: string };
15	  secondaryCTA?: { label: string; href: string };
16	  dashboard: React.ReactNode;
17	}
18	
19	const defaultPrimary = {
20	  label: "Start free trial",
21	  href: "https://inkos.up.railway.app/signup",
22	};
23	
24	const defaultSecondary = {
25	  label: "See it in motion",
26	  href: "/book-a-demo",
27	};
28	
29	function buildHeadlineParts(headline: string, italicWord: string) {
30	  const idx = headline.indexOf(italicWord);
31	  if (idx === -1) {
32	    return { before: headline, italic: "", after: "" };
33	  }
34	  return {
35	    before: headline.slice(0, idx),
36	    italic: italicWord,
37	    after: headline.slice(idx + italicWord.length),
38	  };
39	}
40	
41	export function ProductHero({
42	  feature,
43	  headline,
44	  italicWord,
45	  subhead,
